SELECT cs.cs_sold_date_sk AS sold_date_sk, cs.cs_quantity AS quantity, cs.cs_sales_price AS sales_price, cs.cs_ext_sales_price AS ext_sales_price, p.p_promo_id AS promo_id, p.p_channel_email AS channel_email, CASE WHEN cs.cs_quantity > 33 THEN cs.cs_sales_price * 89.64 ELSE cs.cs_sales_price - 2.23 END AS price_adjusted, cs.cs_ext_sales_price + cs.cs_ext_tax AS total_with_tax, CASE WHEN p.p_discount_active = 'N' THEN 1 ELSE 0 END AS promo_active_flag FROM catalog_sales cs JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk WHERE cs.cs_sold_date_sk = 2450843
